import SwiftUI
import WebKit
import BotChuCore

/// Bundled KaTeX and Mermaid render inside system WebKit without loading remote assets.
/// The document is generated by BotChuCore; model-provided HTML and scripts never reach this view.
/// A reply's web view is made only once the reply comes near the visible part of the chat, and it
/// gets only the libraries its reply uses (Mermaid alone is over 5 MB); a reply that gains math or
/// a diagram as it streams gets that library then. A reply drawn again starts at the height it
/// was last drawn at. A new web view is invisible until its reply has rendered, so the bubble
/// shows, not WebKit's white page or the reply's source, and the reply fades in at its final height.
/// A rendered reply's web view outlives its conversation's view for a while (`RichReplyPool`), so
/// showing the conversation again shows the reply at once. A web view renders one revision of its
/// reply at a time: one written meanwhile waits, only the newest, and the renderer keeps the blocks
/// that haven't changed, with their math and diagrams.
struct RichMarkdownText: View {
    let html: String
    @State private var height: CGFloat

    init(html: String) {
        self.html = html
        _height = State(initialValue: RichMarkdownHeights.height(for: html) ?? 24)
    }

    var body: some View {
        RichMarkdownWebView(html: html, height: $height)
            .frame(height: height)
    }
}

/// The height each rich reply was last drawn at, for the next time it is drawn. Kept by the hash
/// of the reply's HTML, a few bytes each however long the reply.
@MainActor enum RichMarkdownHeights {
    private static var heights: [Int: CGFloat] = [:]
    static let limit = 500

    static var count: Int { heights.count }

    static func height(for html: String) -> CGFloat? { heights[html.hashValue] }

    static func remember(_ height: CGFloat, for html: String) {
        // Only a hint for the first frame: forgetting everything now and then keeps it small.
        if heights.count >= limit { heights.removeAll(keepingCapacity: true) }
        heights[html.hashValue] = height
    }
}

/// The renderers a reply's document needs.
enum RichMarkdownLibrary: String, CaseIterable, Comparable {
    case katex = "katex.min.js"
    case mermaid = "mermaid.min.js"

    /// Read from the markup BotChuCore writes for math and diagrams; reply text is escaped, so it
    /// can't add either.
    static func needed(by html: String) -> Set<RichMarkdownLibrary> {
        var libraries: Set<RichMarkdownLibrary> = []
        if html.contains("class=\"tex\"") { libraries.insert(.katex) }
        if html.contains("class=\"diagram-block\"") { libraries.insert(.mermaid) }
        return libraries
    }

    static func < (lhs: Self, rhs: Self) -> Bool { lhs.rawValue < rhs.rawValue }
}

struct RichMarkdownWebView: NSViewRepresentable {
    @Environment(\.colorScheme) private var colorScheme
    let html: String
    @Binding var height: CGFloat

    func makeCoordinator() -> Coordinator { Coordinator(height: $height) }

    func makeNSView(context: Context) -> ReplyWebContainer {
        let container = ReplyWebContainer()
        container.setContentHuggingPriority(.defaultLow, for: .horizontal)
        context.coordinator.html = html
        context.coordinator.dark = colorScheme == .dark
        context.coordinator.openFileLink = context.environment.openFileLink
        container.makeWebView = { [weak coordinator = context.coordinator] in coordinator?.makeWebView() }
        return container
    }

    func updateNSView(_ container: ReplyWebContainer, context: Context) {
        context.coordinator.height = $height
        context.coordinator.openFileLink = context.environment.openFileLink
        guard context.coordinator.html != html || context.coordinator.dark != (colorScheme == .dark) else { return }
        context.coordinator.html = html
        context.coordinator.dark = colorScheme == .dark
        if let view = container.webView { context.coordinator.render(in: view) }
    }

    static func dismantleNSView(_ container: ReplyWebContainer, coordinator: Coordinator) {
        container.makeWebView = nil
        guard let view = container.webView as? ChatWebView else { return }
        view.navigationDelegate = nil
        view.messages.coordinator = nil
        if !RichReplyPool.park(view) { view.discard() }
    }

    @MainActor final class Coordinator: NSObject, WKNavigationDelegate {
        var height: Binding<CGFloat>
        var html = ""
        var dark = false
        var openFileLink: FileLinkAction?

        init(height: Binding<CGFloat>) { self.height = height }

        /// The reply's rendered web view from the pool when it has one, else a new one.
        func makeWebView() -> WKWebView {
            let view = RichReplyPool.take(html: html, dark: dark) ?? newWebView()
            view.messages.coordinator = self
            view.navigationDelegate = self
            return view
        }

        private func newWebView() -> ChatWebView {
            let controller = WKUserContentController()
            let messages = ReplyMessages()
            controller.add(messages, contentWorld: .defaultClient, name: "layout")
            controller.add(messages, contentWorld: .defaultClient, name: "copyCode")
            controller.addUserScript(WKUserScript(source: RichMarkdownWebView.script("renderer.js"), injectionTime: .atDocumentEnd,
                                                 forMainFrameOnly: true, in: .defaultClient))
            let libraries = RichMarkdownLibrary.needed(by: html)
            for library in libraries.sorted() {
                controller.addUserScript(WKUserScript(source: RichMarkdownWebView.script(library.rawValue), injectionTime: .atDocumentStart,
                                                     forMainFrameOnly: true, in: .defaultClient))
            }
            let configuration = WKWebViewConfiguration()
            configuration.websiteDataStore = RichMarkdownWebView.dataStore
            configuration.userContentController = controller
            let view = ChatWebView(frame: .zero, configuration: configuration, messages: messages)
            view.libraries = libraries
            view.underPageBackgroundColor = .clear
            // Without WebKit's white behind the page, which a web view put back in a window shows
            // until its page has painted there (kept ones stay in theirs, `RichReplyPool`). The
            // setting is WebKit's own but not public, hence the check; without it, that's white.
            if view.responds(to: NSSelectorFromString("_setDrawsBackground:")) { view.setValue(false, forKey: "drawsBackground") }
            // Shown by the reply's first height (`received`).
            view.alphaValue = 0
            view.setContentHuggingPriority(.defaultLow, for: .horizontal)
            view.loadFileURL(RichMarkdownWebView.document, allowingReadAccessTo: RichMarkdownWebView.assets)
            return view
        }

        func render(in view: WKWebView) {
            guard let view = view as? ChatWebView, view.loaded else { return }
            // One render at a time: the newest revision written meanwhile follows it.
            guard !view.busy else {
                if view.waiting { view.skipped += 1 }
                view.waiting = true
                return
            }
            let key = RichReplyPool.Key(html: html, dark: dark)
            view.busy = true
            view.waiting = false
            view.rendered = key
            view.revision += 1
            view.renders += 1
            let missing = RichMarkdownLibrary.needed(by: key.html).subtracting(view.libraries)
            guard !missing.isEmpty else { return Self.renderReply(key, in: view) }
            // The reply gained math or a diagram: its library first, in the renderer's world.
            view.libraries.formUnion(missing)
            let source = missing.sorted().map { RichMarkdownWebView.script($0.rawValue) }.joined(separator: "\n;\n") + "\n;true"
            view.evaluateJavaScript(source, in: nil, in: .defaultClient) { [weak view] _ in
                guard let view else { return }
                Self.renderReply(key, in: view)
            }
        }

        private static func renderReply(_ key: RichReplyPool.Key, in view: ChatWebView) {
            // Pass content as an argument, never interpolate model text into executable JavaScript.
            view.callAsyncJavaScript("await window.renderReply(html, dark, revision);",
                                     arguments: ["html": key.html, "dark": key.dark, "revision": view.revision],
                                     in: nil, in: .defaultClient) { [weak view] _ in
                guard let view else { return }
                view.busy = false
                // What the view shows now, if it changed meanwhile, also when another reply's
                // view has taken this web view from the pool.
                guard let coordinator = view.messages.coordinator,
                      view.rendered != RichReplyPool.Key(html: coordinator.html, dark: coordinator.dark) else {
                    view.waiting = false
                    return
                }
                coordinator.render(in: view)
            }
        }

        func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
            (webView as? ChatWebView)?.loaded = true
            render(in: webView)
        }

        func received(_ message: WKScriptMessage) {
            guard message.frameInfo.isMainFrame else { return }
            // Only a height of the revision rendered last counts: the page reports again once a
            // newer render finishes, and a web view taken from the pool numbers its renders on.
            if message.name == "layout", let layout = message.body as? [String: Any],
               let value = layout["height"] as? Double, value.isFinite, value > 0,
               let view = message.webView as? ChatWebView, let rendered = view.rendered,
               layout["revision"] as? Int == view.revision {
                let measured = ceil(value)
                if abs(height.wrappedValue - measured) > 0.5 { height.wrappedValue = measured }
                RichMarkdownHeights.remember(measured, for: rendered.html)
                // The first height comes once the reply has rendered: it fades in after the chat
                // has taken that height.
                if view.alphaValue == 0 {
                    DispatchQueue.main.async { [weak view] in
                        NSAnimationContext.runAnimationGroup { context in
                            context.duration = 0.15
                            view?.animator().alphaValue = 1
                        }
                    }
                }
            } else if message.name == "copyCode", let code = message.body as? String {
                NSPasteboard.general.clearContents()
                NSPasteboard.general.setString(code, forType: .string)
            }
        }

        func webView(_ webView: WKWebView, decidePolicyFor action: WKNavigationAction,
                     decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {
            if action.navigationType == .linkActivated, let url = action.request.url {
                if ReplyLink(url) == .web {
                    NSWorkspace.shared.open(url)
                } else if let link = FileLink.link(fromPage: url) {
                    // A file, from the conversation's folder (#363).
                    openFileLink?(link)
                }
            }
            // Only the initial, app-generated document is allowed to load inside the chat.
            decisionHandler(action.navigationType == .other && action.request.url?.standardizedFileURL == RichMarkdownWebView.document.standardizedFileURL ? .allow : .cancel)
        }
    }

    /// One nonpersistent store for every reply, rather than a new one for each.
    @MainActor static let dataStore = WKWebsiteDataStore.nonPersistent()
    private static let assets = Bundle.module.url(forResource: "ChatRenderer", withExtension: nil)!
    private static let document = assets.appendingPathComponent("index.html")
    private static let scripts: [String: String] = Dictionary(uniqueKeysWithValues:
        ["katex.min.js", "mermaid.min.js", "renderer.js"].map {
            ($0, (try? String(contentsOf: assets.appendingPathComponent($0), encoding: .utf8)) ?? "")
        })
    private static func script(_ name: String) -> String { scripts[name] ?? "" }
}

/// Holds a reply's web view, made only once the reply is within about a screen of the visible
/// part of its scroll view (at once, outside one), so a long chat doesn't make a web view, and
/// load its renderers, for every rich reply in it.
final class ReplyWebContainer: NSView {
    var makeWebView: (() -> WKWebView?)?
    private(set) var webView: WKWebView?
    private weak var watchedClip: NSClipView?

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        watchScrolling()
        makeWebViewIfNear()
    }

    override func setFrameSize(_ newSize: NSSize) {
        super.setFrameSize(newSize)
        makeWebViewIfNear()
    }

    override func setFrameOrigin(_ newOrigin: NSPoint) {
        super.setFrameOrigin(newOrigin)
        makeWebViewIfNear()
    }

    override func layout() {
        super.layout()
        webView?.frame = bounds
        makeWebViewIfNear()
    }

    private func watchScrolling() {
        let clip = window == nil || webView != nil ? nil : enclosingScrollView?.contentView
        guard clip !== watchedClip else { return }
        if let watchedClip {
            NotificationCenter.default.removeObserver(self, name: NSView.boundsDidChangeNotification, object: watchedClip)
        }
        watchedClip = clip
        guard let clip else { return }
        clip.postsBoundsChangedNotifications = true
        NotificationCenter.default.addObserver(self, selector: #selector(scrolled), name: NSView.boundsDidChangeNotification, object: clip)
    }

    @objc private func scrolled(_ notification: Notification) {
        makeWebViewIfNear()
    }

    private func makeWebViewIfNear() {
        guard webView == nil, window != nil, isNearVisibleArea, let view = makeWebView?() else { return }
        webView = view
        view.frame = bounds
        view.autoresizingMask = [.width, .height]
        addSubview(view)
        watchScrolling()
    }

    private var isNearVisibleArea: Bool {
        guard let clip = enclosingScrollView?.contentView else { return true }
        let frame = convert(bounds, to: nil)
        guard frame.width > 0, frame.height > 0 else { return false }
        let visible = clip.convert(clip.bounds, to: nil)
        return frame.intersects(visible.insetBy(dx: 0, dy: -max(visible.height, 400)))
    }
}

/// A reply's web view, with what it has rendered: what goes with it into the pool and back. The
/// outer chat owns vertical scrolling. Horizontal gestures still reach wide tables and code.
final class ChatWebView: WKWebView {
    let messages: ReplyMessages
    /// The document has loaded, so replies can be rendered into it.
    var loaded = false
    /// The libraries it has, or is evaluating.
    var libraries: Set<RichMarkdownLibrary> = []
    /// The reply and appearance it last rendered.
    var rendered: RichReplyPool.Key?
    /// Its renders, numbered: a render under way, a revision waiting for it, and how many started
    /// and how many revisions were replaced while waiting, never rendered.
    var revision = 0
    var busy = false
    var waiting = false
    var renders = 0
    var skipped = 0

    init(frame: NSRect, configuration: WKWebViewConfiguration, messages: ReplyMessages) {
        self.messages = messages
        super.init(frame: frame, configuration: configuration)
    }

    required init?(coder: NSCoder) { fatalError("not used") }

    override func scrollWheel(with event: NSEvent) {
        if abs(event.scrollingDeltaY) >= abs(event.scrollingDeltaX) { nextResponder?.scrollWheel(with: event) }
        else { super.scrollWheel(with: event) }
    }

    /// Done with for good: stops it and lets go of its renderer.
    func discard() {
        removeFromSuperview()
        stopLoading()
        navigationDelegate = nil
        configuration.userContentController.removeAllScriptMessageHandlers()
    }
}

/// Passes a web view's messages to the view showing it now, which changes when the web view is
/// shown again from the pool. Weak, as the web view's controller keeps its handlers.
@MainActor final class ReplyMessages: NSObject, WKScriptMessageHandler {
    weak var coordinator: RichMarkdownWebView.Coordinator?

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        coordinator?.received(message)
    }
}

/// Rendered replies' web views, kept once their conversation's view goes, so showing that
/// conversation again shows its math and diagrams at once rather than loading and rendering each
/// again. They wait hidden in their window: a web view taken out of its window and put back draws
/// nothing until its page has painted there again, a frame or two. Each has a WebKit process of its
/// own, about 85 MB of memory with Mermaid and 20 MB with KaTeX alone (`footprint`, macOS 27), so
/// the pool keeps only the most recent within `budget`, each for at most `keep` without being
/// shown, and none under memory pressure.
@MainActor enum RichReplyPool {
    struct Key: Hashable {
        var html: String
        var dark: Bool
    }

    private struct Parked {
        let view: ChatWebView
        let since: Date
    }

    /// Oldest first.
    private static var parked: [Parked] = []
    /// What the kept web views may take together, in MB.
    static let budget = 200
    static let keep: TimeInterval = 10 * 60
    private static var expiry: Timer?
    private static var pressure: DispatchSourceMemoryPressure?

    static var count: Int { parked.count }
    static var cost: Int { parked.reduce(0) { $0 + cost(of: $1.view) } }
    static func cost(of view: ChatWebView) -> Int { view.libraries.contains(.mermaid) ? 85 : 20 }

    /// Keeps a web view whose reply has rendered; false when it isn't kept.
    static func park(_ view: ChatWebView, now: Date = Date()) -> Bool {
        guard view.loaded, view.rendered != nil, view.alphaValue == 1, !view.isLoading,
              let content = view.window?.contentView else { return false }
        holder(in: content).addSubview(view)
        parked.append(Parked(view: view, since: now))
        while cost > budget { parked.removeFirst().view.discard() }
        watch()
        return parked.last?.view === view
    }

    /// A kept web view that last rendered this reply in this appearance, no longer kept.
    static func take(html: String, dark: Bool) -> ChatWebView? {
        let key = Key(html: html, dark: dark)
        guard let index = parked.lastIndex(where: { $0.view.rendered == key }) else { return nil }
        return parked.remove(at: index).view
    }

    /// Lets go of the web views kept longer than `keep`.
    static func expire(now: Date = Date()) {
        while let oldest = parked.first, now.timeIntervalSince(oldest.since) > keep { parked.removeFirst().view.discard() }
        if parked.isEmpty {
            expiry?.invalidate()
            expiry = nil
        }
    }

    static func removeAll() {
        let views = parked.map(\.view)
        parked.removeAll()
        views.forEach { $0.discard() }
        expire()
    }

    /// Where kept web views wait: in their window, hidden, so out of sight, focus and accessibility.
    private static func holder(in content: NSView) -> NSView {
        if let holder = content.subviews.first(where: { $0 is ReplyHolder }) { return holder }
        let holder = ReplyHolder(frame: content.bounds)
        holder.isHidden = true
        holder.autoresizingMask = [.width, .height]
        content.addSubview(holder, positioned: .below, relativeTo: nil)
        return holder
    }

    private final class ReplyHolder: NSView {}

    private static func watch() {
        if expiry == nil {
            expiry = Timer.scheduledTimer(withTimeInterval: 60, repeats: true) { _ in MainActor.assumeIsolated { expire() } }
        }
        guard pressure == nil else { return }
        let source = DispatchSource.makeMemoryPressureSource(eventMask: [.warning, .critical], queue: .main)
        source.setEventHandler { MainActor.assumeIsolated { removeAll() } }
        source.activate()
        pressure = source
    }
}
